  1→//! Feedback storage (JSONL format).
  2→
  3→use std::fs::{self, File, OpenOptions};
  4→use std::io::{BufRead, BufReader, Write};
  5→use std::path::PathBuf;
  6→
  7→use anyhow::{Context, Result};
  8→
  9→use super::{FeedbackEntry, FeedbackStatus};
 10→use crate::session::SessionId;
 11→
 12→/// Storage for feedback entries.
 13→pub struct FeedbackStore {
 14→    path: PathBuf,
 15→}
 16→
 17→impl FeedbackStore {
 18→    /// Create a new feedback store.
 19→    pub fn new(path: impl Into<PathBuf>) -> Self {
 20→        Self { path: path.into() }
 21→    }
 22→
 23→    /// Get the store path.
 24→    pub fn path(&self) -> &PathBuf {
 25→        &self.path
 26→    }
 27→
 28→    /// Ensure the parent directory exists.
 29→    fn ensure_dir(&self) -> Result<()> {
 30→        if let Some(parent) = self.path.parent() {
 31→            fs::create_dir_all(parent)
 32→                .with_context(|| format!("Failed to create directory {:?}", parent))?;
 33→        }
 34→        Ok(())
 35→    }
 36→
 37→    /// Append a feedback entry.
 38→    pub fn append(&self, entry: &FeedbackEntry) -> Result<()> {
 39→        self.ensure_dir()?;
 40→
 41→        let mut file = OpenOptions::new()
 42→            .create(true)
 43→            .append(true)
 44→            .open(&self.path)
 45→            .with_context(|| format!("Failed to open {:?}", self.path))?;
 46→
 47→        let json = serde_json::to_string(entry)?;
 48→        writeln!(file, "{}", json)?;
 49→
 50→        Ok(())
 51→    }
 52→
 53→    /// List all feedback entries.
 54→    pub fn list_all(&self) -> Result<Vec<FeedbackEntry>> {
 55→        self.read_entries(|_| true)
 56→    }
 57→
 58→    /// List feedback by status.
 59→    pub fn list_by_status(&self, status: FeedbackStatus) -> Result<Vec<FeedbackEntry>> {
 60→        self.read_entries(|e| e.status == status)
 61→    }
 62→
 63→    /// List feedback by tag.
 64→    pub fn list_by_tag(&self, tag: &str) -> Result<Vec<FeedbackEntry>> {
 65→        self.read_entries(|e| e.tags.iter().any(|t| t == tag))
 66→    }
 67→
 68→    /// List feedback by session.
 69→    pub fn list_by_session(&self, session_id: &SessionId) -> Result<Vec<FeedbackEntry>> {
 70→        self.read_entries(|e| e.session_id.as_ref() == Some(session_id))
 71→    }
 72→
 73→    /// Update an entry by ID.
 74→    pub fn update(&self, id: &str, updater: impl FnOnce(&mut FeedbackEntry)) -> Result<bool> {
 75→        let mut entries = self.list_all()?;
 76→        let mut found = false;
 77→
 78→        for entry in &mut entries {
 79→            if entry.id == id {
 80→                updater(entry);
 81→                found = true;
 82→                break;
 83→            }
 84→        }
 85→
 86→        if found {
 87→            self.rewrite_all(&entries)?;
 88→        }
 89→
 90→        Ok(found)
 91→    }
 92→
 93→    /// Get an entry by ID.
 94→    pub fn get(&self, id: &str) -> Result<Option<FeedbackEntry>> {
 95→        let entries = self.read_entries(|e| e.id == id)?;
 96→        Ok(entries.into_iter().next())
 97→    }
 98→
 99→    /// Read entries matching a predicate.
100→    fn read_entries(
101→        &self,
102→        predicate: impl Fn(&FeedbackEntry) -> bool,
103→    ) -> Result<Vec<FeedbackEntry>> {
104→        if !self.path.exists() {
105→            return Ok(Vec::new());
106→        }
107→
108→        let file = File::open(&self.path)?;
109→        let reader = BufReader::new(file);
110→        let mut entries = Vec::new();
111→
112→        for line in reader.lines() {
113→            let line = line?;
114→            if line.trim().is_empty() {
115→                continue;
116→            }
117→            if let Ok(entry) = serde_json::from_str::<FeedbackEntry>(&line) {
118→                if predicate(&entry) {
119→                    entries.push(entry);
120→                }
121→            }
122→        }
123→
124→        Ok(entries)
125→    }
126→
127→    /// Rewrite all entries (for updates).
128→    fn rewrite_all(&self, entries: &[FeedbackEntry]) -> Result<()> {
129→        self.ensure_dir()?;
130→
131→        let mut file = File::create(&self.path)?;
132→        for entry in entries {
133→            let json = serde_json::to_string(entry)?;
134→            writeln!(file, "{}", json)?;
135→        }
136→
137→        Ok(())
138→    }
139→}
