  1→//! Remote configuration fetching.
  2→//!
  3→//! This module provides functionality for fetching configuration files
  4→//! from remote URLs.
  5→
  6→use anyhow::{anyhow, Context, Result};
  7→use std::collections::HashMap;
  8→use std::path::PathBuf;
  9→use std::time::Duration;
 10→
 11→/// Fetches remote configuration files with caching.
 12→///
 13→/// # Example
 14→///
 15→/// ```no_run
 16→/// use bivvy::config::RemoteFetcher;
 17→/// use std::time::Duration;
 18→///
 19→/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
 20→///
 21→/// // Fetch a remote config file
 22→/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
 23→/// ```
 24→pub struct RemoteFetcher {
 25→    /// Request timeout.
 26→    timeout: Duration,
 27→    /// Cache directory for downloaded configs.
 28→    cache_dir: PathBuf,
 29→    /// HTTP client.
 30→    client: reqwest::blocking::Client,
 31→}
 32→
 33→impl RemoteFetcher {
 34→    /// Create a fetcher with the specified timeout.
 35→    pub fn new(timeout: Duration) -> Self {
 36→        let cache_dir = dirs::cache_dir()
 37→            .unwrap_or_else(|| PathBuf::from("~/.cache"))
 38→            .join("bivvy")
 39→            .join("remote-configs");
 40→
 41→        Self {
 42→            timeout,
 43→            cache_dir,
 44→            client: reqwest::blocking::Client::builder()
 45→                .timeout(timeout)
 46→                .build()
 47→                .expect("Failed to create HTTP client"),
 48→        }
 49→    }
 50→
 51→    /// Create a fetcher with a custom cache directory.
 52→    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
 53→        Self {
 54→            timeout,
 55→            cache_dir,
 56→            client: reqwest::blocking::Client::builder()
 57→                .timeout(timeout)
 58→                .build()
 59→                .expect("Failed to create HTTP client"),
 60→        }
 61→    }
 62→
 63→    /// Fetch a configuration file from a URL.
 64→    pub fn fetch(&self, url: &str) -> Result<String> {
 65→        // Check cache first
 66→        if let Some(cached) = self.check_cache(url)? {
 67→            return Ok(cached);
 68→        }
 69→
 70→        // Fetch from remote
 71→        let content = self.fetch_remote(url)?;
 72→
 73→        // Cache the result
 74→        self.save_cache(url, &content)?;
 75→
 76→        Ok(content)
 77→    }
 78→
 79→    /// Fetch a configuration file, bypassing cache.
 80→    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
 81→        self.fetch_remote(url)
 82→    }
 83→
 84→    /// Fetch with authentication header.
 85→    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
 86→        let response = self
 87→            .client
 88→            .get(url)
 89→            .header(&auth.header_name, &auth.header_value)
 90→            .send()
 91→            .with_context(|| format!("Failed to fetch {}", url))?;
 92→
 93→        if !response.status().is_success() {
 94→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
 95→        }
 96→
 97→        response
 98→            .text()
 99→            .with_context(|| format!("Failed to read response from {}", url))
100→    }
101→
102→    fn fetch_remote(&self, url: &str) -> Result<String> {
103→        let response = self
104→            .client
105→            .get(url)
106→            .send()
107→            .with_context(|| format!("Failed to fetch {}", url))?;
108→
109→        if !response.status().is_success() {
110→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
111→        }
112→
113→        response
114→            .text()
115→            .with_context(|| format!("Failed to read response from {}", url))
116→    }
117→
118→    fn check_cache(&self, url: &str) -> Result<Option<String>> {
119→        let cache_path = self.cache_path(url);
120→        if cache_path.exists() {
121→            let content = std::fs::read_to_string(&cache_path)?;
122→            Ok(Some(content))
123→        } else {
124→            Ok(None)
125→        }
126→    }
127→
128→    fn save_cache(&self, url: &str, content: &str) -> Result<()> {
129→        let cache_path = self.cache_path(url);
130→        if let Some(parent) = cache_path.parent() {
131→            std::fs::create_dir_all(parent)?;
132→        }
133→        std::fs::write(&cache_path, content)?;
134→        Ok(())
135→    }
136→
137→    fn cache_path(&self, url: &str) -> PathBuf {
138→        use sha2::{Digest, Sha256};
139→        let mut hasher = Sha256::new();
140→        hasher.update(url.as_bytes());
141→        let hash = hex::encode(hasher.finalize());
142→        self.cache_dir.join(format!("{}.yml", hash))
143→    }
144→
145→    /// Clear the cache for a specific URL.
146→    pub fn clear_cache(&self, url: &str) -> Result<()> {
147→        let cache_path = self.cache_path(url);
148→        if cache_path.exists() {
149→            std::fs::remove_file(&cache_path)?;
150→        }

