  1→//! Version checking against latest release.
  2→
  3→use anyhow::{Context, Result};
  4→use chrono::{DateTime, Utc};
  5→use serde::{Deserialize, Serialize};
  6→use std::fs;
  7→use std::path::PathBuf;
  8→
  9→/// Current version of bivvy.
 10→pub const VERSION: &str = env!("CARGO_PKG_VERSION");
 11→
 12→/// GitHub API URL for releases.
 13→const GITHUB_API_URL: &str = "https://api.github.com/repos/bivvy-dev/bivvy/releases/latest";
 14→
 15→/// How often to check for updates (1 day).
 16→const CHECK_INTERVAL_SECS: i64 = 86400;
 17→
 18→/// Information about an available update.
 19→#[derive(Debug, Clone, Serialize, Deserialize)]
 20→pub struct UpdateInfo {
 21→    /// Current version.
 22→    pub current: String,
 23→    /// Latest available version.
 24→    pub latest: String,
 25→    /// Whether an update is available.
 26→    pub update_available: bool,
 27→    /// Release URL.
 28→    pub release_url: Option<String>,
 29→    /// When this check was performed.
 30→    pub checked_at: DateTime<Utc>,
 31→}
 32→
 33→/// Cached update check result.
 34→#[derive(Debug, Clone, Serialize, Deserialize)]
 35→struct UpdateCache {
 36→    /// Last update info.
 37→    info: UpdateInfo,
 38→    /// When the cache was written.
 39→    cached_at: DateTime<Utc>,
 40→}
 41→
 42→/// Check for available updates.
 43→///
 44→/// Returns cached result if within check interval.
 45→pub fn check_for_updates() -> Option<UpdateInfo> {
 46→    // Check cache first
 47→    if let Some(cached) = load_cache() {
 48→        let age = Utc::now()
 49→            .signed_duration_since(cached.cached_at)
 50→            .num_seconds();
 51→        if age < CHECK_INTERVAL_SECS {
 52→            return Some(cached.info);
 53→        }
 54→    }
 55→
 56→    // Fetch latest version
 57→    match fetch_latest_version() {
 58→        Ok(info) => {
 59→            // Cache the result
 60→            let _ = save_cache(&info);
 61→            Some(info)
 62→        }
 63→        Err(_) => {
 64→            // Return cached result even if expired
 65→            load_cache().map(|c| c.info)
 66→        }
 67→    }
 68→}
 69→
 70→/// Check for updates without using cache.
 71→pub fn check_for_updates_fresh() -> Result<UpdateInfo> {
 72→    fetch_latest_version()
 73→}
 74→
 75→/// Fetch the latest version from GitHub.
 76→fn fetch_latest_version() -> Result<UpdateInfo> {
 77→    let client = reqwest::blocking::Client::builder()
 78→        .user_agent("bivvy")
 79→        .timeout(std::time::Duration::from_secs(10))
 80→        .build()?;
 81→
 82→    let response: serde_json::Value = client
 83→        .get(GITHUB_API_URL)
 84→        .send()?
 85→        .json()
 86→        .context("Failed to parse GitHub API response")?;
 87→
 88→    let tag = response["tag_name"]
 89→        .as_str()
 90→        .context("No tag_name in response")?
 91→        .trim_start_matches('v');
 92→
 93→    let release_url = response["html_url"].as_str().map(String::from);
 94→
 95→    let update_available = is_newer_version(tag, VERSION);
 96→
 97→    Ok(UpdateInfo {
 98→        current: VERSION.to_string(),
 99→        latest: tag.to_string(),
100→        update_available,
101→        release_url,
102→        checked_at: Utc::now(),
103→    })
104→}
105→
106→/// Compare versions to check if `latest` is newer than `current`.
107→fn is_newer_version(latest: &str, current: &str) -> bool {
108→    let parse_version = |v: &str| -> Vec<u32> {
109→        v.split('.')
110→            .take(3)
111→            .filter_map(|s| s.parse().ok())
112→            .collect()
113→    };
114→
115→    let latest_parts = parse_version(latest);
116→    let current_parts = parse_version(current);
117→
118→    // Compare component by component
119→    for (l, c) in latest_parts.iter().zip(current_parts.iter()) {
120→        if l > c {
121→            return true;
122→        }
123→        if l < c {
124→            return false;
125→        }
126→    }
127→
128→    // If all components equal, check if latest has more components
129→    latest_parts.len() > current_parts.len()
130→}
131→
132→/// Get the cache file path.
133→fn cache_path() -> Option<PathBuf> {
134→    dirs::cache_dir().map(|d| d.join("bivvy").join("update_check.json"))
135→}
136→
137→/// Load cached update info.
138→fn load_cache() -> Option<UpdateCache> {
139→    let path = cache_path()?;
140→    let content = fs::read_to_string(path).ok()?;
141→    serde_json::from_str(&content).ok()
142→}
143→
144→/// Save update info to cache.
145→fn save_cache(info: &UpdateInfo) -> Result<()> {
146→    let path = cache_path().context("No cache directory")?;
147→
148→    if let Some(parent) = path.parent() {
149→        fs::create_dir_all(parent)?;
150→    }

